    getWhatsAppTemplates: {
        parameters: {
            query: {
                /** @description WhatsApp account ID */
                accountId: string;
                /** @description Exact template name; returns every language variant of that family. */
                name?: string;
                /** @description Exact language code (e.g. en_US). */
                language?: string;
                status?: "APPROVED" | "REJECTED" | "PENDING" | "PAUSED" | "DISABLED" | "IN_APPEAL" | "PENDING_DELETION";
            };
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description Templates retrieved successfully */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        success?: boolean;
                        templates?: {
                            /** @description WhatsApp template ID */
                            id?: string;
                            name?: string;
                            /** @enum {string} */
                            status?: "APPROVED" | "PENDING" | "REJECTED";
                            /** @enum {string} */
                            category?: "AUTHENTICATION" | "MARKETING" | "UTILITY";
                            language?: string;
                            /** @description Only when a custom TTL is set; absent while the category default applies. */
                            message_send_ttl_seconds?: number;
                            components?: Record<string, never>[];
                        }[];
                    };
                };
            };
            /** @description accountId is required or WABA ID not found */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
            401: components["responses"]["Unauthorized"];
            /** @description WhatsApp account not found */
            404: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
        };
    };
    createWhatsAppTemplate: {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody: {
            content: {
                "application/json": {
                    /** @description WhatsApp account ID */
                    accountId: string;
                    /** @description Template name (lowercase, letters/numbers/underscores, must start with a letter) */
                    name: string;
                    /**
                     * @description Template category
                     * @enum {string}
                     */
                    category: "AUTHENTICATION" | "MARKETING" | "UTILITY";
                    /** @description Template language code (e.g., en_US) */
                    language: string;
                    /**
                     * @description Variable style: POSITIONAL ({{1}}, the default) or NAMED ({{customer_name}}). Named templates provide examples via body_text_named_params / header_text_named_params. Inferred as NAMED when omitted but a named-params example is present.
                     * @enum {string}
                     */
                    parameter_format?: "POSITIONAL" | "NAMED" | "positional" | "named";
                    /** @description Template components (header, body, footer, buttons, carousel, limited_time_offer). Required for custom templates, omit when using library_template_name. */
                    components?: components["schemas"]["WhatsAppTemplateComponent"][];
                    /**
                     * @description Name of a pre-built template from Meta's template library (e.g., "appointment_reminder",
                     *     "auto_pay_reminder_1", "address_update"). When provided, the template is pre-approved
                     *     by Meta with no review wait. Omit components when using this field.
                     */
                    library_template_name?: string;
                    /**
                     * @description Optional body customizations for library templates. Available options depend on the
                     *     template (e.g., add_contact_number, add_learn_more_link, add_security_recommendation,
                     *     add_track_package_link, code_expiration_minutes).
                     */
                    library_template_body_inputs?: Record<string, never>;
                    /**
                     * @description Optional button customizations for library templates. Each item specifies button type
                     *     and configuration (e.g., URL, phone number, quick reply).
                     */
                    library_template_button_inputs?: {
                        /** @enum {string} */
                        type?: "quick_reply" | "url" | "phone_number";
                        url?: {
                            base_url?: string;
                        };
                        phone_number?: string;
                    }[];
                    /** @description Delivery validity window in seconds: a message not delivered within it is dropped. Range depends on category: AUTHENTICATION 30 to 900, UTILITY 30 to 43200 (12h), MARKETING 43200 to 2592000 (30 days); -1 (create only) keeps the 30-day default on AUTHENTICATION and UTILITY. Meta defaults to 600 for AUTHENTICATION and 30 days otherwise. If Meta later recategorises the template, it clears the TTL (read it back to check). */
                    message_send_ttl_seconds?: number;
                };
            };
        };
        responses: {
            /** @description Template created (pre-approved for library templates, pending review for custom) */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        success?: boolean;
                        template?: {
                            id?: string;
                            name?: string;
                            /** @description APPROVED for library templates, PENDING for custom */
                            status?: string;
                            category?: string;
                            language?: string;
                            /** @description Echoed when supplied on the request. */
                            message_send_ttl_seconds?: number;
                        };
                    };
                };
            };
            /** @description Validation error (invalid name format, missing fields, invalid category) */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
            401: components["responses"]["Unauthorized"];
            /** @description WhatsApp account not found */
            404: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
        };
    };
